NAME = 'Est: Estonian Bible'
BOOK = 'II Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus ja Silvaanus ja Timoteos tessalooniklaste Kogudusele Jumalas, meie Isas, ja Issandas Jeesuses Kristuses.',
        2: 'Armu teile ja rahu Jumalalt, meie Isalt, ja Issandalt Jeesuselt Kristuselt!',
        3: 'Me oleme alati kohustatud Jumalat tänama teie eest, vennad, nõnda nagu on sünnis, sest et teie usk vägevasti kasvab ja armastus jõudsasti edeneb igaühes teie kõikide seas üksteise vastu,',
        4: 'nõnda et me isegi teist kiitleme Jumala Kogudustes, teie kannatlikkusest ja usust, kõigis teie tagakiusamistes ja viletsusis, mida te kannatate',
        5: 'Jumala õige kohtu tõestuseks, et teid arvataks Jumala riiki väärt olevat, mille pärast te ka kannatate,',
        6: 'kui see kuidagi on õige Jumala ees, et teie vaevajaile tasutaks vaevamisega',
        7: 'ja teile, keda vaevatakse, antaks hingamist ühes meiega, kui Issand Jeesus ilmub taevast Oma väe Inglitega',
        8: 'tuleleegis ja maksab kätte neile, kes ei tunne Jumalat ja kes ei alistu meie Issanda Jeesuse Kristuse Evangeeliumile,',
        9: 'kes saavad nuhtluseks igavese hukatuse, hülgamise Issanda palge eest ja Tema vägevuse auhiilgusest,',
        10: 'kui Ta sel päeval tuleb, et austatud olla Oma pühades ja imestatav kõigi usklike seas, sest et meie tunnistust teie kohta on ustud.',
        11: 'Selleks me palumegi alati teie eest, et meie Jumal peaks teid kutsumisväärseks ja teeks täielikuks kõik teie hea meele tubliduse ja teie usu teo väes,',
        12: 'et meie Issanda Jeesuse Kristuse nime austataks teie sees ja teid Tema sees meie Jumala ja meie Issanda Jeesuse Kristuse armu mööda.',
    },
    2: {
        1: 'Aga me palume teid, vennad, meie Issanda Jeesuse Kristuse tulemise ja meie kokkusaamise pärast Temaga,',
        2: 'et te ei annaks endid niipea kõigutada sinna ja tänna eemale õigest meelest ega heidutada ei vaimu läbi ega sõna läbi või kirja läbi, otsekui oleks see meie lähetatud, nagu peaks Issanda päev olema käes.',
        3: 'Ärgu ükski teid petku mingil kombel; sest see päev ei tule mitte enne, kui on tulnud ärataganemine ja saanud avalikuks ülekohtu-inimene, hukatusepoeg,',
        4: 'kes paneb vastu ja tõstab enese üle kõige, mida nimetatakse Jumalaks või jumalateenistuseks, nii et ta istub Jumala templisse ja ütleb enese olevat Jumala.',
        5: 'Eks te mäleta, et ma seda teile ütlesin, kui olin alles teie juures?',
        6: 'Ja nüüd te teate, mis takistab teda saamast avalikuks omal ajal.',
        7: 'Sest ülekohtu saladus on juba mõjumas; ainult peab enne vahelt kõrvaldatama see, kes teda siiamaani takistab;',
        8: 'ja siis saab avalikuks ülekohtune - kelle Issand Jeesus hävitab Oma suu vaimuga ja kellele ta teeb otsa Oma tulemise ilmumisega -',
        9: 'kelle tulemine sünnib saatana võimu mõjustusel igasuguses valeväes ja valetunnustähtedega ja valeimetegudega',
        10: 'ja igasuguse ülekohtu pettuses neile, kes hukka lähevad, sellepärast et nad ei võtnud vastu tõearmastust, et nad oleksid võinud pääseda.',
        11: 'Ja sellepärast Jumal läkitab neile vägeva eksituse, et nad hakkavad uskuma valet,',
        12: 'et mõistetaks hukka kõik need, kes ei ole uskunud tõde, vaid kellel on olnud hea meel ülekohtust.',
        13: 'Aga me peame alati tänama Jumalat teie eest, Issanda armastatud vennad, et Jumal algusest teid on valinud õndsuseks Vaimu pühitsemise ja tõeusu kaudu,',
        14: 'milleks ta on teidki kutsunud meie Evangeeliumi läbi, et te kätte saaksite meie Issanda Jeesuse Kristuse au.',
        15: 'Siis seiske nüüd, vennad, ja pidage kinni neist õpetusist, mis te meilt olete õppinud suusõnal või kirja teel.',
        16: 'Aga meie Issand Jeesus Kristus Ise ja Jumal, meie Isa, Kes meid on armastanud ja meile on andnud igavese troosti ja hea lootuse armuannina,',
        17: 'trööstigu teie südameid ja kinnitagu teid igasuguses heas teos ja sõnas!',
    },
    3: {
        1: 'Lõppeks, vennad, paluge meie eest, et Issanda sõna leviks ja et see tõuseks ausse nõnda nagu teiegi juures,',
        2: 'ja et me pääseksime nurjatute ja kurjade inimeste käest. Sest usk ei ole mitte igaühe oma.',
        3: 'Aga Issand on ustav, Kes teid kinnitab ja kurja eest hoiab.',
        4: 'Ja me loodame teist Issandas, et te nüüd ja ka edaspidi teete, mida me käsime.',
        5: 'Ent Issand juhtigu teie südamed Jumala armastuse ja Kristuse kannatlikkuse poole.',
        6: 'Aga me käsime teid, vennad, meie Issanda Jeesuse Kristuse nimel hoiduda igast vennast, kes elab korratut elu ja mitte seda pärimust mööda, mille olete meilt saanud.',
        7: 'Sest te teate ise, kuidas te peate meie eeskuju järgi elama, sest me ei ole elanud korratult teie keskel',
        8: 'ega ole kellegi juures leiba muidu söönud, vaid oleme vaeva ja rängeldamisega ööd ja päevad teinud tööd, et mitte kedagi teie seast koormata;',
        9: 'ei mitte, et meil poleks selleks meelevalda, vaid et me annaksime teile head eeskuju käia meie järel.',
        10: 'Sest ka siis, kui olime teie juures, seadsime nii, et kes ei taha tööd teha, ärgu ka söögu.',
        11: 'Me kuuleme ju, et mõned teie seast elavad korratut elu ega tee tööd, vaid janditavad.',
        12: 'Ent niisuguseid me käsime ja manitseme Issandas Jeesuses Kristuses, et nad vaikselt tööd tehes sööksid omaenese leiba!',
        13: 'Kuid teie, vennad, ärge tüdige head tegemast!',
        14: 'Aga kui keegi meie sõna, mis meie kirja kaudu on öeldud, ei võta kuulda, siis pidage teda silmas ja ärge tehke tegemist temaga, et ta häbeneks.',
        15: 'Ometi ärge pidage teda vaenlaseks, vaid hoiatage teda kui venda.',
        16: 'Aga Rahuissand Ise andku teile rahu alati ja igal viisil! Issand olgu teie kõikidega!',
        17: 'See tervitus on minu, Pauluse käega; see on tunnuseks igas kirjas; nõnda ma kirjutan.',
        18: 'Meie Issanda Jeesuse Kristuse arm olgu teie kõikidega!',
    },
}
